head.script:
// 화면 리사이징

scwin.gIsurCd;
scwin.gSeq;
scwin.gComNm;
scwin.contnId;
scwin.gDate;
scwin.ToDay = new Date();
scwin.yyyyList = parseInt(scwin.ToDay.getYear(), 10) + 8;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.checkCond();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
        // 특례적용일 또는 년도 있는 부분 선택시 수정화면으로 이동
        else {
            scwin.contnId = "U";
            const url = "/dsclmgt/ULDSTF39302.gfm";
            const winTitle = "제약바이오특례기업 관리 상세화면";
            await $c.frame.CreateDialogFrame("ULDSTF39302", url, winTitle, 200, 100, 735, 630, "window");
            scwin.contnId = "";
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39300.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.checkCond();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF39300.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "제약바이오특례기업관리", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        scwin.contnId = "I";
        const options = {
            id: "ULDSTF39302",
            title: "제약바이오특례기업 등록",
            type: "browserPopup",
            width: "735px",
            height: "630px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/dsclmgt/ULDSTF39302.gfm", options);
        scwin.contnId = "";
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39300.btn_Input_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39300.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39300.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF39300.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.top = "31px";
        Grd_com_isur.style.left = "78px";
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF39300.Grd_com_isur_OnKillFocus" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    let str = "";
    for (let i = scwin.yyyyList; i >= 2018; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_strt_YYYY.CBData = str;
    cmb_end_YYYY.CBData = str;
    cmb_strt_YYYY.setValue("2018");
};

/**
 * @method
 * @name checkCond
 * @description check Cond 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkCond = function() {
    scwin.setItemGridHeaderCheck();
    scwin.search();
};

/**
 * @method
 * @name setItemGridHeaderCheck
 * @description dataid 생성
 * @returns {void}
 * @hidden N
 */
scwin.setItemGridHeaderCheck = function() {
    let headerString = "";
    headerString += "SPECL_COM_SEQ:STRING(6),ISUR_CD:STRING(5),COM_ABBRV:STRING(255),APFM_SUBMIT_DD:STRING(8),SPECL_STRT_DD:STRING(8),SKIL_VALU_GRD_NM:STRING(100),SKIL_VALU_ACQST_DD:STRING(8),VALU_INST_NM:STRING(100),SPECL_COM_ADM_REMK:STRING(2000),LST_CHG_DDTM:STRING(14),LST_CHG_EMP_NO:STRING(6),";
    for (let i = scwin.yyyyList; i >= 2018; i--) {
        if (i === '2018') {
            headerString += "YYYY_" + i + ":STRING(1)";
        } else {
            headerString += "YYYY_" + i + ":STRING(1),";
        }
    }
    // alert(headerString);

    // dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_List.insertRow();
};

/**
 * @method
 * @name setBasicHeader
 * @description 고정된 그리드 생성
 * @param {*} grdObj grdObj
 * @returns {void}
 * @hidden N
 */
scwin.setBasicHeader = function(grdObj) {
    grdObj.ToolTip = "use=true;header=true;alt=true;createtime=1000;destroytime=30000;fontsize=9;color=#0f0f0f;backcolor=white;edgecolor=green;";
    grdObj.FillArea = "true";
    grdObj.AutoResizingWithHeader = "true";
    let basic = "";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='번호' id='NO' align='center' width='30' show='true' value='{currow}' </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='회사코드' id='ISUR_CD' align='center' width='75'  show='true' sort='True'  </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='시퀀스' id='SPECL_COM_SEQ' align='center' width='80'  show='false' </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "bgcolor='#FFFF99' ";
    basic += "name='회사명' id='COM_ABBRV' align='left' width='170' cursor='hand' show='true' sort='True'  </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='신청서제출일' id='APFM_SUBMIT_DD' show='true' mask='XXXX-XX-XX' align='center' width='100' sort='True' </fC>\n";
    basic += "<fC>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='특례적용일' id='SPECL_STRT_DD' show='true' mask='XXXX-XX-XX' align='center' width='90' sort='True' </fC>\n";

    /*	basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
		basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
		basic += "name='기술평가등급' id='SKIL_VALU_GRD_NM' align='center' width='100'  show='true' sort='True'  </C>\n";

		basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
		basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
		basic += "name='기술성평가획득일' id='SKIL_VALU_ACQST_DD' show='true' mask='XXXX-XX-XX' align='center' width='120' sort='True' </C>\n";

		basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
		basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
		basic += "name='전문평가기관명' id='VALU_INST_NM' align='center' width='120'  show='true' sort='True'  </C>\n";
     */
    grdObj.Format = basic;
};

// 동적 그리드 생성(년도)

/**
 * @method
 * @name setMultiHeader
 * @description 기본헤더
 * @param {*} grdObj grdObj
 * @returns {void}
 * @hidden N
 */
scwin.setMultiHeader = function(grdObj) {
    // 기본헤더
    scwin.setBasicHeader(grdObj);

    // Grid Style
    const GRID_STYLE_CTAG = " width=80 align='center' headbgcolor=\"#598fd5\" headcolor=\"#ffffff\" color=\"#343434\" sort='True' ";

    // grid format 계층태그상수
    const LEVEL_ONE_BEGIN_TAG = "<C>";
    const LEVEL_ONE_END_TAG = "</C>\n";

    // 그리드포멧결과
    let gridFormat = "";
    const gSTRT_YYYY = cmb_strt_YYYY.getValue();
    const gEND_YYYY = cmb_end_YYYY.getValue();
    for (let i = gSTRT_YYYY; i <= gEND_YYYY; i++) {
        gridFormat += LEVEL_ONE_BEGIN_TAG;
        gridFormat += "id=\"YYYY_" + i + "\"" + " name=\"" + i + "년\"" + GRID_STYLE_CTAG;
        gridFormat += LEVEL_ONE_END_TAG;
    }
    grdObj.Format += gridFormat;
    scwin.setEndHeader(grdObj);
};

/**
 * @method
 * @name setEndHeader
 * @description 고정된 그리드 생성
 * @param {*} grdObj grdObj
 * @returns {void}
 * @hidden N
 */
scwin.setEndHeader = function(grdObj) {
    let basic = "";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='기술평가등급' id='SKIL_VALU_GRD_NM' align='center' width='100'  show='true' sort='True'  </C>\n";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='기술성평가획득일' id='SKIL_VALU_ACQST_DD' show='true' mask='XXXX-XX-XX' align='center' width='120' sort='True' </C>\n";
    basic += "<C>color='#343434' headalign='center' sumbgcolor='#fefaef' headvalign='center' sumcolor='#343434' ";
    basic += "headbgcolor='#598fd5' headcolor='#ffffff' ";
    basic += "name='전문평가기관명' id='VALU_INST_NM' align='center' width='120'  show='true' sort='True'  </C>\n";
    grdObj.Format += basic;
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    scwin.setMultiHeader(grd_Grid);
    const url_list = "/ExceptionRuleAdm.do?method=listExceptionRuleAdm";
    const url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&STRT_YYYY=" + cmb_strt_YYYY.getValue() + "&END_YYYY=" + cmb_end_YYYY.getValue() + "&SCREN_ID=" + 'ULDSTF39300.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // 그리드의 데이타 조회
    dts_List.DataID = encodeURI(url_list + url_cond);
    dts_List.reset();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
    scwin.gComNm = dts_List.getCellData(Number(obj), "COM_ABBRV");
    scwin.gSeq = dts_List.getCellData(Number(obj), "SPECL_COM_SEQ");
};
